modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.HighPass;
end Baseline;
model FINDING00824
  extends Modelica.Electrical.Analog.Examples.OpAmps.HighPass(f=0);
end FINDING00824;
model FINDING00825
  extends Modelica.Electrical.Analog.Examples.OpAmps.HighPass(fG=0);
end FINDING00825;
model FINDING00820
  extends Modelica.Electrical.Analog.Examples.OpAmps.HighPass(derivative(R1=0));
end FINDING00820;
model FinalFINDING00824
  extends Modelica.Electrical.Analog.Examples.OpAmps.HighPass(final f=0);
end FinalFINDING00824;
model FinalFINDING00825
  extends Modelica.Electrical.Analog.Examples.OpAmps.HighPass(final fG=0);
end FinalFINDING00825;
model FinalFINDING00820
  extends Modelica.Electrical.Analog.Examples.OpAmps.HighPass(derivative(final R1=0));
end FinalFINDING00820;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00824\n");
simulate(FINDING00824, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00825\n");
simulate(FINDING00825, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00820\n");
simulate(FINDING00820, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00824\n");
simulate(FinalFINDING00824, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00825\n");
simulate(FinalFINDING00825, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00820\n");
simulate(FinalFINDING00820, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00824\n");
system("./Baseline -override f=0 -r=FINDING00824_override.csv");
print("AUDIT_OVERRIDE FINDING00825\n");
system("./Baseline -override fG=0 -r=FINDING00825_override.csv");
print("AUDIT_OVERRIDE FINDING00820\n");
system("./Baseline -override derivative.R1=0 -r=FINDING00820_override.csv");
